if (!b->written) {
	struct bkey_format f = b->data->format;

	if (btree_err_on(f.key_u64s < 2,
		     -BCH_ERR_btree_node_read_err_must_retry,
		     c, ca, b, NULL, NULL,
		     btree_node_bad_format,
		     "invalid bkey format: key_u64s %u", f.key_u64s)) {
		ret = -BCH_ERR_btree_node_read_err_must_retry;
		goto fsck_err;
	}

	btree_node_set_format(b, f);
}

